function validateStructures(value){if(value==null)return[];if(!Array.isArray(value)||value.length>80)throw Error('隔断、区域与设施最多 80 项');const ids=new Set(),pointTypes=['area','desk','firedoor','power','ups','cooling','entrysign','battery','gas'];return value.map(item=>{if(!item||typeof item!=='object'||!['glass','solid',...pointTypes].includes(item.type)||typeof item.id!=='string'||!(/^[A-Za-z0-9-]{1,100}$/).test(item.id)||ids.has(item.id))throw Error('隔断或设施格式不正确');ids.add(item.id);const label=text(item.label,40).trim();if(pointTypes.includes(item.type)){if(item.type==='area'&&!label)throw Error('区域标识需要名称');const x=planCoordinate(item.x),y=planCoordinate(item.y),turn=num(item.turn??0,0,270);if(x===null||y===null||turn%90)throw Error('设施位置或朝向不正确');const result={id:item.id,type:item.type,label,x,y,turn};if(item.type==='battery'){result.cols=num(item.cols??16,1,32);result.rows=num(item.rows??4,1,6);result.levels=num(item.levels??2,1,10);if(result.cols*result.rows*result.levels>256)throw Error('电池架示意容量最多 256 节');if(item.count==null&&result.cols===4&&result.rows===4&&result.levels===8){result.cols=16;result.rows=4;result.levels=2}result.count=num(item.count??result.cols*result.rows*result.levels,1,256);if(result.count>result.cols*result.rows*result.levels)throw Error('电池节数不能超过架位容量')}if(item.type==='gas')result.count=num(item.count??1,1,8);return result}const x1=planCoordinate(item.x1),y1=planCoordinate(item.y1),x2=planCoordinate(item.x2),y2=planCoordinate(item.y2);if([x1,y1,x2,y2].some(v=>v===null)||Math.hypot(x2-x1,y2-y1)<.015)throw Error('隔断端点不完整或太短');return{id:item.id,type:item.type,label,x1,y1,x2,y2}})}
function validateRoom(value){const v=value&&typeof value==='object'?value:{},base=roomDefaults(),plan=typeof v.plan==='string'?v.plan:'';if(plan&&(!/^data:image\/(webp|jpeg|png);base64,[A-Za-z0-9+/=]+$/.test(plan)||plan.length>2500000))throw Error('平面图格式或大小不正确，请导入本机 JPG、PNG 或 WebP 图片');const hasEntry=v.entryX!=null&&v.entryY!=null;return{plan,imageWidth:num(v.imageWidth??0,0,4000),imageHeight:num(v.imageHeight??0,0,4000),width:num(v.width??0,0,60),depth:num(v.depth??0,0,60),rackScale:num(v.rackScale??100,35,100),northOnTop:['north','east','south','west'].includes(v.northOnTop)?v.northOnTop:'',entrance:['top','right','bottom','left'].includes(v.entrance)?v.entrance:base.entrance,entranceAt:num(v.entranceAt??50,5,95),entryX:hasEntry?planCoordinate(v.entryX):null,entryY:hasEntry?planCoordinate(v.entryY):null,entryFacing:['up','right','down','left'].includes(v.entryFacing)?v.entryFacing:'up',structures:validateStructures(v.structures)}}
